"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5234"],{6842(e,t,r){r.r(t),r.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>i,contentTitle:()=>s,toc:()=>l,assets:()=>p});var n=JSON.parse('{"id":"reference/reports/howtos/createtripreplayreport","title":"How to View and Create Trip Replay Reports","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/reports/howtos/createtripreplayreport.md","sourceDirName":"reference/reports/howtos","slug":"/reference/reports/howtos/createtripreplayreport","permalink":"/personal-av-docs/docs/reference/reports/howtos/createtripreplayreport","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/reports/howtos/createtripreplayreport.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to View and Create Trip Replay Reports","sidebar_label":"How to View and Create Trip Replay Repor","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/reports/howtos/createtripreplayreport","format":"md"}}'),o=r(4848),a=r(8453);let i={title:"How to View and Create Trip Replay Reports",sidebar_label:"How to View and Create Trip Replay Repor",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/reports/howtos/createtripreplayreport",format:"md"},s,p={},l=[];function c(e){let t={a:"a",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/reports/howtos/createtripreplayreport",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"How to View and Create Trip Replay Reports\nThe Trip Replay report shows you an animated view of a trip over the time period selected. As the vehicle/system moves on the map, it is followed by a colored trail that indicates speed and distance covered. Date and time information helps you identify where a system was at a specific time.\nYou can configure the report to show trips within a specific zone, as shown below.\nStart, pause, replay, replay speed and map zoom controls give you options for viewing trip replays.\nCreating a Trip Replay Report\nTo begin, from the Reporting dashboard, click the\nCreate a New Report\nicon.\nAn empty report screen appears.\nSelect a Template\nChoose how often you\u2019d like this report to be run.\nClick:\nSingle\nfor a one-time report\nWeekly\nMonthly\nYearly\nUnder\nReport Properties\n, you can complete the scheduling for your new report. The section below describes how to configure the time and the day on which you\u2019d like your report to run.\nTo run a report immediately, click\nRun Report\n.\nDefine the Report Properties\nThe required fields for creating a valid report are\nType\n,\nName\nand\nRange\n.\nSelect the Report Type\nSelect\nTrip Replay\nfrom the\nType\nmenu.\nThe Report Properties page appears.\nEnter a Name and Description\nGive your report a brief, descriptive name. You may want to use a driver\u2019s name, a vehicle model, and/or the AirLink gateway or router model, depending on the type of report you run.\nBelow the\nName\nfield, you can enter a longer report description. You may want to include the report\u2019s schedule and reporting zone.\nSelect the Reporting Range\nThe Range menu lists the options for the reporting period. You can select a predefined Reporting Range, or configure a Custom range.\nIf scheduling a recurring report, select one of the relative date ranges (\nYesterday\nor\nLast 7 Days\n, for  example). Selecting an absolute range will generate the same results each time.\nIf you click\nCustom\n, a calendar appears, allowing you to select a start date/time and an end date/time for your report.\nSelect Recipient Email Addresses\nClick the\nRecipient Emails\nfield to select the people you would like to be notified when the report is run.\nYou can also manually enter email addresses in this field.\nSelect a Zone\nFor Trip Replay reports, you can specify one inclusion zone.\nLocation data collected outside the \u201CIncluded\u201D zone is not shown in the trip replay.\nThe zones available to you are defined in the\nConfigure > Zones\nsection.\nFor more information, see\nHow to Create a Zone\n.\nSelect Units\nYou can choose to render your reports in metric or imperial units.\nDefine Speed Thresholds\nYou can fine tune the speed levels (low/high) that are indicated by green and red color trails on the map.\nSelect a System\nSelect the system for which you want to run your new report.\nTrip Replay Reports can be run for one system only.\nSelect Advanced Settings: Start and End Dates\nThe Advanced settings are strictly optional. If you enable these settings, you may want to set a reminder (external to ALMS) to notify yourself of the start and end dates.\nClick the\nAdvanced\nbutton to display options for selecting start and end dates for your reports. For example, you can configure a weekly report to run for two months starting one week from today.\nClicking Start Time or Run Until displays a calendar on which you can define a start date/time and end date/time."})]})}function d(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},8453(e,t,r){r.d(t,{R:()=>i,x:()=>s});var n=r(6540);let o={},a=n.createContext(o);function i(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);